INSERT INTO `tiab_meetings` (`id`, `meeting_number`, `district`, `division`, `area`, `theme`, `meeting_date`, `start_time`, `end_time`, `timezone`, `mission`, `quote_text`, `quote_author`, `venue_details`, `created_at`, `updated_at`, `wod_word`, `wod_meaning`, `wod_synonyms`, `wod_example`, `ballot_categories_json`) VALUES
(9, 'Lead Box', 'District 41', 'Division B', 'Area B4', 'Journey', '2026-09-26', '18:00:00', '19:17:00', 'NPT', 'We provide a supportive and positive learning experience in which members are empowered to develop communication and leadership skills, resulting in greater self-confidence and personal growth', '\"Knowing is not enough; we must apply. Willing is not enough; we must do.\"', 'Johann Wolfgang von Goeth', 'Every Wednesday @ 18:00\r\nOnwards in Ground Floor, Library, Himalayan WhieHouse International College, Putalisadak, Kathmandu', '2026-09-26 13:34:10', '2026-09-26 13:34:10', '', '', '', '', '[\"Better Role Takers\",\"Better Evaluator\",\"Better Featured Speaker\",\"Better Table Topic Speaker\"]'),
(10, '#257 Lead Box', 'District 41', 'Division B', 'Area B4', 'Happiness Index', '2026-09-30', '18:15:00', '19:09:00', 'NPT', 'We provide a supportive and positive learning experience in which members are empowered to develop communication and leadership skills, resulting in greater self-confidence and personal growth', '\"Knowing is not enough; we must apply. Willing is not enough; we must do.\"', 'Johann Wolfgang von Goeth', 'Every Thursday @ 18:00\r\nOnwards in 7th Floor, Meeting Hall, Nabil Bank, Ghantaghar Branch, Kathmandu', '2026-09-26 13:50:46', '2026-09-26 13:50:46', '', '', '', '', '[\"Better Role Takers\",\"Better Evaluator\",\"Better Featured Speaker\",\"Better Table Topic Speaker\"]'),
(11, 'Founders and Techspire', 'District 41', 'Division C, A', 'Area C2, A4', 'asvasv', '2026-09-26', '18:00:00', '19:30:00', 'NPT', 'We provide a supportive and positive learning experience in which members are empowered to develop communication and leadership skills, resulting in greater self-confidence and personal growth', '\"Knowing is not enough; we must apply. Willing is not enough; we must do.\"', 'Johann Wolfgang von Goeth', 'Every Thursday @ 18:00\r\nOnwards in 7th Floor, Meeting Hall, Nabil Bank, Ghantaghar Branch, Kathmandu', '2026-09-26 15:15:41', '2026-09-26 15:15:41', '', '', '', '', '[\"Better Role Takers\",\"Better Evaluator\",\"Better Featured Speaker\",\"Better Table Topic Speaker\"]'),
(12, '#116 Tokha', 'District 41', 'Division B', 'Area B3', 'Festivity', '2026-09-29', '18:00:00', '19:17:00', 'NPT', 'We provide a supportive and positive learning experience in which members are empowered to develop communication and leadership skills, resulting in greater self-confidence and personal growth', '\"Knowing is not enough; we must apply. Willing is not enough; we must do.\"', 'Johann Wolfgang von Goeth', 'Every Thursday @ 18:00\r\nOnwards in 7th Floor, Meeting Hall, Nabil Bank, Ghantaghar Branch, Kathmandu', '2026-09-27 12:12:39', '2026-09-27 12:12:39', 'Jubilant', 'Feeling or expressing great happiness and excitement, especially during a celebration.', 'Joyful, festive, cheerful, elated, celebratory', 'The crowd was jubilant as they gathered to celebrate the festival with music, food, and laughter.', '[\"Better Role Takers\",\"Better Evaluator\",\"Better Featured Speaker\",\"Better Table Topic Speaker\"]'),
(13, '#116 Tokha', 'District 41', 'Division B', 'Area B3', 'Festivity', '2026-09-29', '18:15:00', '19:32:00', 'NPT', 'We provide a supportive and positive learning experience in which members are empowered to develop communication and leadership skills, resulting in greater self-confidence and personal growth', 'Festivals are the threads that weave a community together.', 'David Binder', 'Every Tuesday @ 18:15\r\nOnwards in Adhayayan School, Samakhusi,  Kathmandu', '2026-09-27 12:13:13', '2026-09-28 12:30:53', 'Jubilant', 'Feeling or expressing great happiness and excitement, especially during a celebration.', 'Joyful, festive, cheerful, elated, celebratory', 'The crowd was jubilant as they gathered to celebrate the festival with music, food, and laughter.', '[\"Better Role Takers\",\"Better Evaluator\",\"Better Featured Speaker\",\"Better Table Topic Speaker\"]'),
